int countExpensive = 0;
try (Scanner sc = new Scanner(new java.io.File("scan_products.csv")).useDelimiter(",|\r?\n")) {
    while (sc.hasNextInt()) {
        int id = sc.nextInt();
        String name = sc.next();
        double price = sc.nextDouble();
        System.out.printf("id=%d name=%-10s price=%.2f%n", id, name, price);
        if (price > 50) countExpensive++;
    }
} catch (java.io.FileNotFoundException e) { e.printStackTrace(); }

System.out.println("Products > $50: " + countExpensive); // 3

