import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;

String json = "{\"order\":{\"id\":100,\"items\":[\"book\",\"pen\"],\"total\":45.5}}";
ObjectMapper mapper = new ObjectMapper();

// 1. Schema-free Map
Map<String, Object> map = mapper.readValue(json, new TypeReference<Map<String,Object>>() {});
System.out.println("Map: " + map);

// 2. JsonNode tree navigation
JsonNode root = mapper.readTree(json);
JsonNode order = root.get("order");
int orderId = order.get("id").asInt();
double total = order.get("total").asDouble();
JsonNode items = order.get("items");
System.out.println("Order #" + orderId + ", total: " + total);
System.out.print("Items: ");
for (JsonNode item : items) {
    System.out.print(item.asText() + " ");
}
System.out.println();
// Order #100, total: 45.5
// Items: book pen
